import{_ as r,C as o,o as l,c as s,a5 as n,E as i,j as a,a as d}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"按功能区域审查变更","description":"","frontmatter":{"title":"按功能区域审查变更","docId":"user.cloud.changes","translationKey":"user.cloud.changes","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f875a22e66dd822d7ea1344188d8b7b087a23a777e072240a4a3c7c57969f995","translationRevision":"353195b2b412e47763fc0520f40936727eb19f0c56141c8e581b0c811c0e31c7","order":20},"headers":[],"relativePath":"zh/user/cloud/changes.md","filePath":"zh/user/cloud/changes.md","lastUpdated":1794611623000}'),c={name:"zh/user/cloud/changes.md"};function u(h,e,p,v,g,b){const t=o("DemoFrame");return l(),s("div",null,[e[0]||(e[0]=n('<h1 id="review-changes-by-area" tabindex="-1">按功能区域审查变更 <a class="header-anchor" href="#review-changes-by-area" aria-label="Permalink to &quot;按功能区域审查变更 {#review-changes-by-area}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>重置、发送或采纳数据前，了解 <strong>更改</strong> 面板究竟比较什么。你需要已保存的本地内容。Cloud 操作还需要受支持的宿主、对应的同步模式及<a href="./account.html">已登录的账户</a>。名称相同的面板并不都采用相同的传输方式。</p><h2 id="review-events-and-actions-locally" tabindex="-1">在本地审查事件与操作 <a class="header-anchor" href="#review-events-and-actions-locally" aria-label="Permalink to &quot;在本地审查事件与操作 {#review-events-and-actions-locally}&quot;">​</a></h2><ol><li>打开 <strong>自动化</strong>，选择事件或操作，再打开 <strong>更改</strong>。</li><li>阅读提示：此区域将当前定义与本设备保留的参考副本进行比较。首次加载访问会建立该参考，因此没有变更也属正常。</li><li>选择新增、修改或删除的记录，检查前后值。</li><li>仅在希望将当前分区作为新本地参考时选择 <strong>标记为已审查</strong>。这不会上传定义，也不会批准受委托的执行。</li><li>仅在确实要恢复参考状态时使用 <strong>重置为已同步版本</strong>。对于新增记录，重置会移除它；对于修改或删除的记录，会恢复保留的定义。如有需要，请先导出。</li></ol><p>此版本的事件/操作适配器没有用于单条定义的 Cloud 集合。比较结果干净既不代表完成 Cloud 备份，也不能证明另一台电脑收到了编辑。</p><h2 id="review-variables-and-plugins-explicitly" tabindex="-1">明确审查变量与插件 <a class="header-anchor" href="#review-variables-and-plugins-explicitly" aria-label="Permalink to &quot;明确审查变量与插件 {#review-variables-and-plugins-explicitly}&quot;">​</a></h2><p>变量有独立的原生审查式共享流程：先本地保存，再获取候选项、检查比较，最后明确发送、应用/采纳或撤回。秘密值和被阻止的值保持遮蔽，不能通过该路径发送。本地保存从不上传。请参阅<a href="./../automations/variables.html">变量</a>。</p><p>插件更改使用其支持的同步工作区管理插件选择及暂存设置。发布按分区进行，而非逐行单独发送。设置只显示已更改的键名，不暴露值；冲突时可选择本地版或 Cloud 版，不支持任意字段合并。发布前请阅读分区操作及选中的同步模式。</p><p>Cloud 叠加层采用<a href="./../overlays/">库/编辑器</a>的创建与修订流程。此基础版本不提供共享叠加层更改适配器。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">预期结果、状态与恢复 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;预期结果、状态与恢复 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>本地自动化比较和按能力开放的原生共享，在各自区域中可用。产生远程副作用的操作依赖服务，并不表示已通过生产验收。审查过期时，刷新并重新比较。结果未确认时，先检查状态或日志，再创建另一个操作。不要将超时当作没有发生变更的证据。</p>',12)),i(t,{scenario:"cloud",locale:"zh",tour:"changes",title:"演示：Cloud 变更"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[d("运行细节 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "运行细节 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"准备或执行 v1 → v2 迁移前，先备份本地数据，并协调所有设备使用兼容版本。在 setup 依次准备、检查兼容性和预览；分别查看选择、待处理、冲突及仅 v1 项目数量，不要假定全部已同步。要求写入 epoch 头对账户全部 v2 写入不可逆，可能拒绝旧设备。屏障超时代表结果不明，重复调用会再次推进 epoch。后续操作前刷新迁移/epoch 状态和预览；读取 epoch 不证明旧写入已经完成。",-1)),e[3]||(e[3]=a("p",null,"恢复依模式而定：Events/Actions Changes 只比较本地参考，不写 Cloud。已审核 Variables/Plugins 比较过期时重新加载，核对当前修订、账户和清单。缺少插件时使用 setup 清单审核/修复，再生成预览。保留的不明意图应保存 ID/证据并查看历史/状态；技术恢复需要重新审核冻结条目及 Cloud 修订。恢复该意图本身不发送远程写入。无法核对状态时停止，不要创建替代变更绕过不确定性。",-1))])}const _=r(c,[["render",u]]);export{f as __pageData,_ as default};
